"""matplotlib.backends.backend_template — template backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_template import
FigureCanvasTemplate`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasTemplate = _make_canvas('FigureCanvasTemplate', 'png')
FigureManagerTemplate = _make_manager('FigureManagerTemplate')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasTemplate
FigureManager = FigureManagerTemplate

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendTemplate', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show


# ─── Added: missing public names (stub classes/funcs) ────────
class GraphicsContextTemplate:
    """Stub: real matplotlib defines this in the template backend."""
    def __init__(self, *args, **kwargs): pass

class RendererTemplate:
    """Stub: real matplotlib defines this in the template backend."""
    def __init__(self, *args, **kwargs): pass
